"Effect": "Allow",
"Action": [
"mediaconvert:CreateJob"
],
"Resource": [
"arn:aws:mediaconvert:`us-east-1`:`123456789012`:queues/\*",
"arn:aws:mediaconvert:`us-east-1`:`123456789012`:jobTemplates/\*",
